import { existsSync, readFileSync } from "node:fs"
import { join } from "node:path"
import { defineConfig } from "vite"
import react from "@vitejs/plugin-react"
import tailwindcss from "@tailwindcss/vite"

// On Windows, use the LAN certificate generated by mkcert for this machine.
// Environment variables remain available for an explicit certificate override.
const certDirectory = process.env.LOCALAPPDATA
  ? join(process.env.LOCALAPPDATA, "AssessmentMonitoring", "certs")
  : undefined
const httpsCert = process.env.LOCAL_TLS_CERT || (certDirectory && join(certDirectory, "lan.pem"))
const httpsKey = process.env.LOCAL_TLS_KEY || (certDirectory && join(certDirectory, "lan-key.pem"))

if (!httpsCert || !httpsKey || !existsSync(httpsCert) || !existsSync(httpsKey)) {
  throw new Error(
    "Vite HTTPS certificate not found. Generate a trusted LAN certificate with mkcert for 10.10.25.206, " +
    "or set LOCAL_TLS_CERT and LOCAL_TLS_KEY to valid certificate and key files."
  )
}

const https = { cert: readFileSync(httpsCert), key: readFileSync(httpsKey) }

export default defineConfig({
  plugins: [react(), tailwindcss()],
  server: {
    host: true,
    port: 3000,
    strictPort: true,
    allowedHosts: true,
    proxy: {
      "/api": {
        target: "http://127.0.0.1:8080",
        changeOrigin: true,
        ws: true,
      },
    },
    https,
  },
})
